toad_implementation.code_blueprint:
canvas {
  size: 960px 650px;
  fill: #FFFFFF;
  font-family: "Helvetica, sans-serif";
}

>u1Red = #E11D48;
>u2Blue = #2563EB;
>u3Green = #16A34A;
>stationBorder = #111827;

text #networkTitle {
  at: top left of canvas offset 48px 40px;
  content: "METROPOLITAN RAPID TRANSIT NETWORK";
  font-size: 18px;
  font-weight: 700;
  color: #111827;
}

rect #lineU1Horiz {
  at: center of canvas offset 0px -40px;
  size: 760px 12px;
  fill: >u1Red;
  radius: 6px;
}

rect #lineU2Vert {
  at: center of canvas offset 40px 0px;
  size: 12px 480px;
  fill: >u2Blue;
  radius: 6px;
}

circle #junctionCentral {
  at: center of canvas offset 40px -40px;
  size: 32px;
  fill: #FFFFFF;
  stroke: >stationBorder;
  stroke-width: 4px;
}

text #centralLabel {
  at: top right of #junctionCentral offset 12px -16px;
  content: "CENTRAL STATION (U1 / U2)";
  font-size: 14px;
  font-weight: 700;
  color: #111827;
}

circle #stationU1West {
  at: left center of #lineU1Horiz offset 120px 0px;
  size: 18px;
  fill: #FFFFFF;
  stroke: >stationBorder;
  stroke-width: 3px;
}

text #labelWest {
  at: below #stationU1West offset 8px;
  content: "Westpark";
  font-size: 12px;
  font-weight: 600;
  color: #374151;
}
